def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    source = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not source or not marker:
        return out

    for r, c in marker:
        out[r][c] = 0

    mr0, mr1 = min(r for r, c in marker), max(r for r, c in marker)
    mc0, mc1 = min(c for r, c in marker), max(c for r, c in marker)
    # A T-shaped marker (bar at top/bottom) means reflect sideways;
    # a cross marker means reflect downwards.
    rows = {r: {c for rr, c in marker if rr == r} for r in range(mr0, mr1 + 1)}
    cols = {c: {r for r, cc in marker if cc == c} for c in range(mc0, mc1 + 1)}
    horizontal_reflection = (len(rows[mr0]) == mc1 - mc0 + 1 or
                             len(rows[mr1]) == mc1 - mc0 + 1)

    if horizontal_reflection:
        sc0, sc1 = min(c for r, c in source), max(c for r, c in source)
        src_center2 = sc0 + sc1
        marker_center2 = mc0 + mc1
        if marker_center2 >= src_center2:
            # Copy reflected to the right, adjacent to source.
            axis2 = 2 * sc1 + 1
        else:
            # Copy reflected to the left, adjacent to source.
            axis2 = 2 * sc0 - 1
        for r, c in source:
            cc = axis2 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        bottom = max(r for r, c in source)
        for r, c in source:
            rr = 2 * bottom + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    return out
