def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    source = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not source or not marker:
        return out
    for r, c in marker:
        out[r][c] = 0

    sr0, sr1 = min(r for r, c in source), max(r for r, c in source)
    sc0, sc1 = min(c for r, c in source), max(c for r, c in source)
    mr0, mr1 = min(r for r, c in marker), max(r for r, c in marker)
    mc0, mc1 = min(c for r, c in marker), max(c for r, c in marker)
    full_width = mc1 - mc0 + 1
    row_counts = {r: sum(1 for rr, c in marker if rr == r) for r in range(mr0, mr1 + 1)}

    if row_counts[mr0] == full_width:  # T bar at top: reflect source to its right
        for r, c in source:
            cc = 2 * sc1 + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    elif row_counts[mr1] == full_width:  # T bar at bottom: reflect source to its left
        for r, c in source:
            cc = 2 * sc0 - 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:  # centered cross marker: reflect source downwards
        for r, c in source:
            rr = 2 * sr1 + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    return out
